mapper.select:

/*selectMasterMpRqBulkQuotationAddAgentItem*/
SELECT
	KEP_DESCRIPTION,
	KEP_SPECIFICATION,
	KEP_MAKER_PART_NO
FROM KEP_BURQ_RFQ
WHERE BURQ_NO = #{st_burq_no}
AND ITEM_KEY_ID = #{st_item_key_id}
AND AGENT = (SELECT AGENT FROM KEP_BURQ_ITEM WHERE BURQ_NO = #{st_burq_no} AND ITEM_KEY_ID = #{st_item_key_id})


/*selectMasterMpRqBulkQuotationAddAgent*/
SELECT
	AGENT,
	(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME
FROM KEP_BURQ_RFQ
WHERE BURQ_NO = #{st_burq_no}
AND ITEM_KEY_ID = #{st_item_key_id}
AND STATUS = 'K3'
AND AGENT <> (SELECT AGENT FROM KEP_BURQ_ITEM WHERE BURQ_NO = #{st_burq_no} AND ITEM_KEY_ID = #{st_item_key_id})

mapper.update:

/*deleteMasterMpRqBulkQuotationAddAgent*/
DELETE KEP_BURQ_RFQ
WHERE BURQ_NO = #{st_burq_no}
AND	ITEM_KEY_ID = #{st_item_key_id}
AND AGENT = #{AGENT}
AND STATUS = 'K3'
